{
  "implementation": "from fractions import Fraction

def solve(case):
    segments = case['segments']
    budget = case['budget']
    names = [seg['name'] for seg in segments]
    importance = [seg['importance'] for seg in segments]
    minimum = [seg['minimum'] for seg in segments]
    capacity = [seg['capacity'] for seg in segments]
    n = len(segments)
    total_min = sum(minimum)
    total_cap = sum(capacity)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget not within feasible range')
    alloc = list(minimum)
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_score = None
        for i in range(n):
            if alloc[i] < capacity[i]:
                score = Fraction(importance[i], alloc[i] + 1)
                if best_idx == -1 or score > best_score or (score == best_score and i < best_idx):
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            raise ValueError('Cannot allocate remaining budget')
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {names[i]: alloc[i] for i in range(n)}
    total = sum(alloc)
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"
}
